// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, uint256 amount, uint64 lock) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1e24);
        lock = uint64(bound(uint256(lock), 0, 1e6));

        // functioning log file: records messages and returns normally
        FakeLog log = new FakeLog();

        vm.prank(actor);
        c.SetMinSum(amount);
        vm.prank(actor);
        c.SetLogFile(address(log));
        vm.prank(actor);
        c.Initialized();

        // deposit (Put is payable; observe revert bool via low-level call)
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool putOk, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Put.selector, uint256(lock))
        );

        // time passes beyond the unlock time
        vm.warp(block.timestamp + uint256(lock) + 1);

        // withdraw full deposit
        vm.prank(actor);
        (bool collectOk, ) = address(c).call(
            abi.encodeWithSelector(c.Collect.selector, amount)
        );

        // General rule: after correct initialization, a full deposit followed by a
        // timely full withdrawal completes without reverting.
        assertTrue(putOk && collectOk);
    }
}

contract FakeLog {
    function AddMessage(address, uint256, string calldata) public pure {}
}
